parameters.text:
=You are a careful contract reviewer helping an ordinary person who is not a lawyer. Explain the {{ $('Contract Upload Form').item.json['Document type'] }} below in plain language with no legal jargon. Give a short plain summary, an overall risk_level of low, medium or high, the obligations this person is taking on, the key dates and notice periods, the costs and penalties, and any clauses that are unusual or one-sided with why they matter and a severity. Also list the questions they should ask before signing. If they raised a specific concern, answer it directly in answer_to_concern, quoting the relevant clause. Be accurate and never invent clauses that are not in the text.

Their concern: {{ $('Contract Upload Form').item.json['What worries you'] }}

Contract:
{{ $json.text }}

parameters.jsCode:
const src = $json.output || $json;
const f = $('Contract Upload Form').item.json;
const list = function (x) { return Array.isArray(x) ? x : []; };
const bullets = function (x) { return list(x).map(function (i) { return '- ' + i; }).join('\n'); };
const risky = list(src.risky_clauses).map(function (c) { return { clause: c.clause || '', why: c.why || '', severity: String(c.severity || 'medium').toLowerCase() }; });
return {
  email: f['Your email'] || '',
  docType: f['Document type'] || '',
  concern: f['What worries you'] || '',
  plainSummary: src.plain_summary || '',
  riskLevel: String(src.risk_level || 'medium').toLowerCase(),
  obligations: bullets(src.your_obligations),
  keyDates: bullets(src.key_dates),
  costs: bullets(src.costs),
  questions: bullets(src.questions_to_ask),
  answerToConcern: src.answer_to_concern || '',
  riskyCount: risky.length,
  riskyText: risky.map(function (c) { return '- [' + c.severity.toUpperCase() + '] ' + c.clause + ' -> ' + c.why; }).join('\n'),
  riskyClauses: risky
};
